import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type WealthGrowthChartProps = Record<string, any>;

const WealthGrowthChart: React.FC<WealthGrowthChartProps> = ({
  backgroundColor = "#04070a",
  transparentBackground = false,
  durationInSeconds = 12,
  title = "Territorial Extension of Mexico",
  period1Title = "1821–1823 — First Mexican Empire",
  period1Value = 4900000,
  barColor1 = "#ffd700",
  period2Title = "After 1855 — Modern Territorial Definition",
  period2Value = 1964375,
  barColor2 = "#008b8b",
  particleCount = 60,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Cinematic Text & Camera Interpolations
  const titleOpacity = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [15, 45], [30, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const pushInScale = interpolate(frame, [0, durationInSeconds * fps], [0.95, 1.05]);

  // Timings
  const bar1Start = 60; 
  const bar1Duration = 50;
  const bar1End = bar1Start + bar1Duration;

  const bar2Start = bar1End + 45; // Dramatic pause before second bar
  const bar2Duration = 50;
  const bar2End = bar2Start + bar2Duration;

  // Progress Calculations
  const bar1Progress = interpolate(frame, [bar1Start, bar1End], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const bar2Progress = interpolate(frame, [bar2Start, bar2End], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Relative Scaling Logic (100% max width based on the largest value)
  const maxVal = Math.max(period1Value, period2Value);
  const targetPct1 = (period1Value / maxVal) * 100;
  const targetPct2 = (period2Value / maxVal) * 100;

  const currentWidthPct1 = bar1Progress * targetPct1;
  const currentWidthPct2 = bar2Progress * targetPct2;

  const currentVal1 = bar1Progress * period1Value;
  const currentVal2 = bar2Progress * period2Value;

  const text1Opacity = interpolate(frame, [bar1Start, bar1Start + 15], [0, 1], { extrapolateRight: "clamp" });
  const text2Opacity = interpolate(frame, [bar2Start, bar2Start + 15], [0, 1], { extrapolateRight: "clamp" });

  const trailOpacity1 = interpolate(frame, [bar1Start, bar1Start + 10, bar1End - 5, bar1End + 15], [0, 1, 1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const trailOpacity2 = interpolate(frame, [bar2Start, bar2Start + 10, bar2End - 5, bar2End + 15], [0, 1, 1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const formatVal = (v: number) => new Intl.NumberFormat('en-US').format(Math.floor(v)) + " km²";

  // Subtle Atmospheric Dust Particles
  const dustParticles = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => ({
      x: random(`px-${i}`) * 120 - 10,
      y: random(`py-${i}`) * 120 - 10,
      size: random(`ps-${i}`) * 4 + 1,
      opacity: random(`po-${i}`) * 0.4 + 0.1,
      speedY: random(`psy-${i}`) * 0.8 + 0.2,
      speedX: (random(`psx-${i}`) - 0.5) * 0.4,
    }));
  }, [particleCount]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {!transparentBackground && (
        <>
          {/* Deep Navy Vignette / Shadows */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              background: "linear-gradient(135deg, rgba(5, 10, 20, 0.8) 0%, rgba(2, 4, 8, 1) 100%)",
            }}
          />
          {/* Aged Parchment / Haze Center Glow */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              background: "radial-gradient(circle at 50% 40%, rgba(60, 50, 35, 0.2) 0%, transparent 65%)",
            }}
          />
        </>
      )}

      <AbsoluteFill style={{ transform: `scale(${pushInScale})` }}>
        {/* Particle System */}
        <div style={{ position: "absolute", width: "100%", height: "100%", pointerEvents: "none" }}>
          {dustParticles.map((p, i) => {
            const yPos = p.y - frame * p.speedY * 0.1;
            const xPos = p.x + frame * p.speedX * 0.1;
            const blink = (Math.sin(frame * 0.05 + random(`pb-${i}`) * 10) + 1) / 2;
            const op = p.opacity * blink * interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" });
            return (
              <div
                key={`dust-${i}`}
                style={{
                  position: "absolute",
                  left: `${xPos}%`,
                  top: `${yPos}%`,
                  width: p.size,
                  height: p.size,
                  backgroundColor: "#ffe4b5",
                  borderRadius: "50%",
                  boxShadow: "0 0 8px rgba(255, 228, 181, 0.5)",
                  opacity: op,
                }}
              />
            );
          })}
        </div>

        {/* Main Content Layout */}
        <div style={{ 
          display: "flex", 
          flexDirection: "column", 
          width: "100%", 
          height: "100%",
          padding: "15% 8%", 
        }}>
          
          {/* Main Title */}
          <div style={{ flex: "0 0 auto", marginBottom: "12%" }}>
            <h1
              style={{
                fontFamily: playfairFamily,
                fontSize: 76,
                color: "#f4f0e6",
                textAlign: "center",
                fontWeight: 600,
                lineHeight: 1.15,
                margin: 0,
                textShadow: "0 0 30px rgba(255, 215, 0, 0.15), 0 2px 10px rgba(255, 215, 0, 0.25), 0 -1px 2px rgba(255, 255, 255, 0.2)",
                transform: `translateY(${titleY}px)`,
                opacity: titleOpacity,
              }}
            >
              {title}
            </h1>
          </div>

          {/* Data Comparison Areas */}
          <div style={{ flex: "1 1 auto", display: "flex", flexDirection: "column", gap: 100, justifyContent: "center", paddingBottom: "25%" }}>
            
            {/* Period 1 */}
            <div style={{ display: "flex", flexDirection: "column", gap: 15, width: "100%" }}>
              <div style={{ opacity: text1Opacity }}>
                <h2 style={{ fontFamily: interFamily, fontSize: 32, color: "#cbd5e1", margin: 0, fontWeight: 300 }}>
                  {period1Title}
                </h2>
              </div>
              
              <div style={{ width: "100%", height: 40 }}>
                <div style={{
                  width: `${Math.max(currentWidthPct1, 0)}%`,
                  height: "100%",
                  backgroundColor: barColor1,
                  borderRadius: "0 4px 4px 0",
                  boxShadow: `0 0 25px ${barColor1}40`,
                  position: "relative"
                }}>
                  {currentWidthPct1 > 1 && (
                    <div style={{
                      position: "absolute",
                      right: 0, 
                      top: "50%", 
                      transform: "translate(50%, -50%)",
                      width: 6, 
                      height: "180%", 
                      backgroundColor: "#fff",
                      borderRadius: 10,
                      boxShadow: `0 0 20px 5px ${barColor1}, 0 0 40px 10px ${barColor1}`,
                      opacity: trailOpacity1
                    }} />
                  )}
                </div>
              </div>
              
              <div style={{ opacity: text1Opacity }}>
                <div style={{ 
                  fontFamily: interFamily, fontSize: 52, fontWeight: 700, color: "#fff", 
                  textShadow: "0 2px 10px rgba(0,0,0,0.5)"
                }}>
                  {formatVal(currentVal1)}
                </div>
              </div>
            </div>

            {/* Period 2 */}
            <div style={{ display: "flex", flexDirection: "column", gap: 15, width: "100%" }}>
              <div style={{ opacity: text2Opacity }}>
                <h2 style={{ fontFamily: interFamily, fontSize: 32, color: "#cbd5e1", margin: 0, fontWeight: 300 }}>
                  {period2Title}
                </h2>
              </div>
              
              <div style={{ width: "100%", height: 40 }}>
                <div style={{
                  width: `${Math.max(currentWidthPct2, 0)}%`,
                  height: "100%",
                  backgroundColor: barColor2,
                  borderRadius: "0 4px 4px 0",
                  boxShadow: `0 0 25px ${barColor2}40`,
                  position: "relative"
                }}>
                  {currentWidthPct2 > 1 && (
                    <div style={{
                      position: "absolute",
                      right: 0, 
                      top: "50%", 
                      transform: "translate(50%, -50%)",
                      width: 6, 
                      height: "180%", 
                      backgroundColor: "#fff",
                      borderRadius: 10,
                      boxShadow: `0 0 20px 5px ${barColor2}, 0 0 40px 10px ${barColor2}`,
                      opacity: trailOpacity2
                    }} />
                  )}
                </div>
              </div>
              
              <div style={{ opacity: text2Opacity }}>
                <div style={{ 
                  fontFamily: interFamily, fontSize: 52, fontWeight: 700, color: "#fff", 
                  textShadow: "0 2px 10px rgba(0,0,0,0.5)"
                }}>
                  {formatVal(currentVal2)}
                </div>
              </div>
            </div>

          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default WealthGrowthChart;